import math


def simpson(f, a, b, n):
    h = (b - a) / n
    total = f(a) + f(b)
    for i in range(1, n):
        if i % 2 == 1:
            total = total + 4 * f(a + i * h)
        else:
            total = total + 2 * f(a + i * h)
    return total * h / 3


def spiral_length(t):
    # the antiderivative of sqrt(t^2 + 1) from Example 6
    return 0.5 * (t * math.sqrt(t * t + 1) + math.log(t + math.sqrt(t * t + 1)))


def polar_length(label, f, fp, a, b, exact):
    speed = lambda t: math.sqrt(f(t)**2 + fp(t)**2)
    print(f"{label}: Simpson {simpson(speed, a, b, 200):.4f}, exact {exact}")


polar_length("Example 1 · r = 3", lambda t: 3, lambda t: 0, 0, 2 * math.pi, f"{6 * math.pi:.4f}")
polar_length("Example 2 · r = 2cos(theta)", lambda t: 2 * math.cos(t), lambda t: -2 * math.sin(t), 0, math.pi, f"{2 * math.pi:.4f}")
polar_length("Example 3 · the cardioid", lambda t: 1 + math.cos(t), lambda t: -math.sin(t), 0, 2 * math.pi, "8")
polar_length("Example 5 · r = e^theta", math.exp, math.exp, 0, 1, f"{math.sqrt(2) * (math.e - 1):.4f}")
polar_length("Example 6 · r = theta", lambda t: t, lambda t: 1, 0, 2 * math.pi, f"{spiral_length(2 * math.pi):.4f}")
polar_length("Example 8 · r = 1 + 2cos(theta)", lambda t: 1 + 2 * math.cos(t), lambda t: -2 * math.sin(t), 0, 2 * math.pi, "no formula")
polar_length("Example 9 · the hose", lambda t: 0.02 * t, lambda t: 0.02, 0, 10 * math.pi, f"{0.02 * spiral_length(10 * math.pi):.4f}")

