import math


def simpson(f, a, b, n):
    h = (b - a) / n
    total = f(a) + f(b)
    for i in range(1, n):
        if i % 2 == 1:
            total = total + 4 * f(a + i * h)
        else:
            total = total + 2 * f(a + i * h)
    return total * h / 3


def value(text):
    # "2pi" means 2π, "pi" means π, and anything else is a plain number
    if text.endswith("pi"):
        if text == "pi":
            return math.pi
        return float(text[:-2]) * math.pi
    return float(text)


curves = {
    "circle": (lambda t: 3, lambda t: 0),
    "shifted": (lambda t: 2 * math.cos(t), lambda t: -2 * math.sin(t)),
    "cardioid": (lambda t: 1 + math.cos(t), lambda t: -math.sin(t)),
    "log": (math.exp, math.exp),
    "spiral": (lambda t: t, lambda t: 1),
    "rose": (lambda t: math.cos(2 * t), lambda t: -2 * math.sin(2 * t)),
}

count = int(input())
for i in range(count):
    name, a_text, b_text = input().split()
    f, fp = curves[name]
    a, b = value(a_text), value(b_text)
    speed = lambda t: math.sqrt(f(t)**2 + fp(t)**2)
    L = simpson(speed, a, b, 200)
    print(f"Problem {i + 1}: {name} from {a_text} to {b_text}, length {L:.4f}")
